private void permutationsHelper(int[] nums, List<Integer> current, List<List<Integer>> permutations) {
        if (current.size() == nums.length) {
            permutations.add(new ArrayList<>(current));
            return;
        }

        for (int i = 0; i < nums.length; i++) {
            if (current.contains(nums[i])) {
                continue;
            }
            current.add(nums[i]);
            permutationsHelper(nums, current, permutations);
            current.remove(current.size() - 1);
        }
    }

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums.length == 0) {
        return result;
    } else if (nums.length == 1) {
        result.add(new ArrayList<>(Arrays.asList(nums[0])));
        return result;
    }

    for (int i = 0; i < nums.length; i++) {
        int current = nums[i];
        nums[i] = nums[0];
        nums[0] = current;
        List<List<Integer>> remainingPermutations = permute(Arrays.copyOfRange(nums, 1, nums.length));
        for (List<Integer> permutation : remainingPermutations) {
            permutation.add(0, current);
        }
        result.addAll(remainingPermutations);
    }

    return result;
}

