}

private static void findOilDeposit(char[][] grid, int i, int j) {
    if (i < 0 || j < 0 || i >= grid.length || j >= grid[i].length || grid[i][j] != '@') {
        return;
    }
    grid[i][j] = '~';
    findOilDeposit(grid, i + 1, j);
    findOilDeposit(grid, i - 1, j);
    findOilDeposit(grid, i, j + 1);
    findOilDeposit(grid, i, j - 1);
}

