    maze[end[0]][end[1]] = true;

    // Loop through each path between adjacent n-tersections
    for (int[] path : paths) {
        // If the path connects two n-tersections that are not yet discovered, mark them as discovered
        if (!maze[path[0]][path[1]] && !maze[path[2]][path[3]]) {
            maze[path[0]][path[1]] = true;
            maze[path[2]][path[3]] = true;
        }
    }

    // If the starting n-tersection is not discovered, return "cannot be travelled"
    if (!maze[start[0]][start[1]]) {
