public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Create a status array to keep track of visited n-tersections
    boolean[] visited = new boolean[n];

    // Mark the starting n-tersection as visited
    visited[start[0]] = true;

    // Create a stack to keep track of the n-tersections to visit next
    Stack<int[]> stack = new Stack<>();

    // Add the starting n-tersection to the stack
    stack.push(start);

    // Keep looping until the stack is empty
    while (!stack.isEmpty()) {
        // Get the current n-tersection from the stack
        int[] current = stack.pop();

        // Check if the current n-tersection is the ending n-tersection
        if (current[0] == end[0] && current[1] == end[1]) {
            // If this is the ending n-tersection, return "can be travelled"
            return "can be travelled";
        }

        // Check if the current n-tersection has been visited before
        if (visited[current[0]]) {
            // If the current n-tersection has been visited before, return "cannot be travelled"
            return "cannot be travelled";
        }

        // Mark the current n-tersection as visited
        visited[current[0]] = true;

        // Get the paths from the current n-tersection to its adjacent n-tersections
        int[] adjacent = paths[current[0]];

        // Loop through the paths and add the n-tersections to the stack if they have not been visited before
        for (int i = 0; i < adjacent.length; i++) {
            int next = adjacent[i];
            if (!visited[next]) {
                stack.push(new int[] { next, current[1] });
            }
        }
    }

    // If the stack is empty and no path has been found, return "cannot be travelled"
    return "cannot be travelled";
}

