public double trimMean(int[] arr) {
    int n = arr.length;
    // Remove 5% of smallest and largest elements
    int toRemove = n / 20;
    Arrays.sort(arr);
    int[] trimmedArr = Arrays.copyOfRange(arr, toRemove, n - toRemove);
    // Calculate mean of remaining elements
    double mean = trimmedArr.stream().mapToDouble(x -> x).average().orElse(0.0);
    return mean;
}

public double trimMean(int[] arr) {
    int n = arr.length;
    int filteredLen = (int) Math.ceil(n * 0.8);
    Arrays.sort(arr);
    int[] filtered = new int[filteredLen];
    System.arraycopy(arr, (int) Math.ceil(n * 0.05), filtered, 0, filteredLen);
    return Arrays.stream(filtered).average().orElse(0.0);
}

