public double trimMean(int[] arr) {
    // Sort the array
    Arrays.sort(arr);

    // Find the size of the trimmed portion
    int size = (int) (arr.length / 100 * 5);

    // Sum the elements in the trimmed portion
    int sum = 0;
    for (int i = size; i < arr.length - size; i++) {
        sum += arr[i];
    }

    // Return the mean of the trimmed portion
    return (double) sum / (arr.length - 2 * size);
}

