}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 == 1 || k < 2) return false;
    int[] count = new int[k];
    for (int num : arr) count[(num % k + k) % k]++;
    int total = 0;
    for (int num : count) total += num;
    return total % 2 == 0;
}

