public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] dist = new int[n]; // Stores the minimum distance from the current node to node 0
    Arrays.fill(dist, Integer.MAX_VALUE); // Initialize all values to infinity
    dist[0] = 0; // Distance from node 0 to node 0 is 0

    Queue<Integer> queue = new LinkedList<>(); // Queue to do BFS
    queue.offer(0); // Add node 0 as the first element of the queue

    while (!queue.isEmpty()) {
        int node = queue.poll(); // Get the next node from the queue
        for (int neighbor : getNeighbors(edges, node)) { // Iterate through the neighbors of the current node
            if (hasApple[neighbor]) { // If the neighbor has an apple, increment the distance by 2
                dist[neighbor] = Math.min(dist[neighbor], dist[node] + 2);
            } else { // If the neighbor does not have an apple, increment the distance by 1
                dist[neighbor] = Math.min(dist[neighbor], dist[node] + 1);
            }
            queue.offer(neighbor); // Add the neighbor to the queue
        }
    }

    return dist[0]; // Return the minimum distance from the current node to node 0
}

private List<Integer> getNeighbors(int[][] edges, int node) {
    List<Integer> neighbors = new ArrayList<>();
    for (int[] edge : edges) {
        if (node == edge[0]) { // If the current node is the first element of the edge, add the second element as a neighbor
            neighbors.add(edge[1]);
        } else if (node == edge[1]) { // If the current node is the second element of the edge, add the first element as a neighbor
            neighbors.add(edge[0]);
        }
    }
    return neighbors;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] parents = new int[n];
    int[] depths = new int[n];
    Stack<Integer> stack = new Stack<>();
    stack.push(0);
    parents[0] = 0;
    depths[0] = 0;
    while (!stack.isEmpty()) {
        int node = stack.pop();
        for (int i = 0; i < edges.length; i++) {
            int neighbor = edges[i][0] == node ? edges[i][1] : edges[i][0];
            if (parents[neighbor] == 0) {
                parents[neighbor] = node;
                depths[neighbor] = depths[node] + 1;
                stack.push(neighbor);
            }
        }
    }
    int totalTime = 0;
    for (int i = 0; i < hasApple.length; i++) {
        if (hasApple[i]) {
            int depth = depths[i];
            totalTime += (depth + 1) * 2;
        }
    }
    return totalTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a variable to store the minimum time required to collect apples
    int minTime = 0;

    // Initialize a variable to keep track of the number of apples collected
    int numApples = 0;

    // Create a list to store the nodes that have been visited
    List<Integer> visitedNodes = new ArrayList<>();

    // Add the starting node to the visited nodes list
    visitedNodes.add(0);

    // Loop until all nodes have been visited
    while (visitedNodes.size() < n) {
        // Get the current node
        int currentNode = visitedNodes.get(visitedNodes.size() - 1);

        // If the current node has an apple, add it to the number of apples collected
        if (hasApple[currentNode]) {
            numApples++;
        }

        // Get the neighbors of the current node
        List<Integer> neighbors = getNeighbors(edges, currentNode);

        // Add the neighbors that have not been visited to the visited nodes list
        for (int neighbor : neighbors) {
            if (!visitedNodes.contains(neighbor)) {
                visitedNodes.add(neighbor);
            }
        }

        // Increment the minimum time by 1
        minTime++;
    }

    // Return the minimum time required to collect all the apples and return to the starting node
    return minTime + numApples;
}

private List<Integer> getNeighbors(int[][] edges, int node) {
    List<Integer> neighbors = new ArrayList<>();
    for (int[] edge : edges) {
        if (edge[0] == node) {
            neighbors.add(edge[1]);
        } else if (edge[1] == node) {
            neighbors.add(edge[0]);
        }
    }
    return neighbors;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int result = 0;
    for (int i = 0; i < edges.length; i++) {
