}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n == 0) {
        return 0;
    }
    boolean[] visited = new boolean[n];
    int[] dist = new int[n];
    Arrays.fill(dist, Integer.MAX_VALUE);
    dist[0] = 0;
    Queue<Integer> queue = new LinkedList<>();
    queue.add(0);
    while (!queue.isEmpty()) {
        int node = queue.poll();
        visited[node] = true;
        for (int neighbor : edges[node]) {
            if (!visited[neighbor] && hasApple[neighbor]) {
                dist[neighbor] = Math.min(dist[neighbor], dist[node] + 1);
                queue.add(neighbor);
            }
        }
    }
    return dist[0];
}

