public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    while (s.length() > 0) {
        // Step 1: Pick the smallest character from s and append it to the result
        int smallestIndex = -1;
        char smallestChar = Character.MAX_VALUE;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < smallestChar) {
                smallestChar = c;
                smallestIndex = i;
            }
        }
        result.append(smallestChar);

        // Step 2: Pick the smallest character from s which is greater than the last appended character to the result and append it
        while (true) {
            smallestIndex = -1;
            smallestChar = Character.MAX_VALUE;
            for (int i = 0; i < s.length(); i++) {
                char c = s.charAt(i);
                if (c < smallestChar && c > result.charAt(result.length() - 1)) {
                    smallestChar = c;
                    smallestIndex = i;
                }
            }
            if (smallestIndex == -1) {
                break;
            } else {
                result.append(smallestChar);
            }
        }

        // Step 3: Pick the largest character from s and append it to the result
        int largestIndex = -1;
        char largestChar = Character.MIN_VALUE;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c > largestChar) {
                largestChar = c;
                largestIndex = i;
            }
        }
        result.append(largestChar);

        // Step 4: Pick the largest character from s which is smaller than the last appended character to the result and append it
        while (true) {
            largestIndex = -1;
            largestChar = Character.MIN_VALUE;
            for (int i = 0; i < s.length(); i++) {
                char c = s.charAt(i);
                if (c > largestChar && c < result.charAt(result.length() - 1)) {
                    largestChar = c;
                    largestIndex = i;
                }
            }
            if (largestIndex == -1) {
                break;
            } else {
                result.append(largestChar);
            }
        }
    }
    return result.toString();
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    char[] charArray = s.toCharArray();
    Arrays.sort(charArray);
    while (result.length() < s.length()) {
        char minChar = charArray[0];
        result.append(minChar);
        charArray[0] = ' ';
        for (int i = 1; i < s.length(); i++) {
            if (charArray[i] > minChar && charArray[i] < charArray[1]) {
                result.append(charArray[i]);
                charArray[i] = ' ';
            }
        }
        char maxChar = charArray[s.length() - 1];
        result.append(maxChar);
        charArray[s.length() - 1] = ' ';
        for (int i = s.length() - 2; i >= 0; i--) {
            if (charArray[i] < maxChar && charArray[i] > charArray[s.length() - 2]) {
                result.append(charArray[i]);
                charArray[i] = ' ';
            }
        }
    }
    return result.toString();
}

