public int minCostClimbingStairs(int[] cost) {
    int[] memo = new int[cost.length];
    Arrays.fill(memo, -1);
    return minCostClimbingStairsHelper(cost, 0, memo);
}

private int minCostClimbingStairsHelper(int[] cost, int index, int[] memo) {
    if (index >= cost.length) {
        return 0;
    }
    if (memo[index] != -1) {
        return memo[index];
    }
    int minCost = Integer.MAX_VALUE;
    for (int i = 0; i < 2; i++) {
        int currentCost = minCostClimbingStairsHelper(cost, index + 1, memo);
        minCost = Math.min(minCost, currentCost + cost[index]);
    }
    memo[index] = minCost;
    return minCost;
}

public int minCostClimbingStairs(int[] cost) {
    int[] dp = new int[cost.length];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < cost.length; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }
    return Math.min(dp[cost.length - 1], dp[cost.length - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int dp0 = cost[0];
    int dp1 = cost[1];
    for (int i = 2; i < n; i++) {
        int dp2 = Math.min(dp0, dp1) + cost[i];
        dp0 = dp1;
        dp1 = dp2;
    }
    return Math.min(dp0, dp1);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int dp0 = 0, dp1 = 0;
    for (int i = 0; i < n; i++) {
        int tmp = dp0;
        dp0 = Math.min(dp0, dp1) + cost[i];
        dp1 = tmp;
    }
    return Math.min(dp0, dp1);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int dp = new int[n];

    dp[0] = cost[0];
    dp[1] = Math.min(cost[0], cost[1]);

    for (int i = 2; i < n; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }

    return Math.min(dp[n - 1], dp[n - 2]);
}

