public boolean hasAllCodes(String s, int k) {
    // Check if s is a valid binary string and k is a valid length
    if (s == null || s.length() == 0 || k <= 0 || k > s.length()) {
        return false;
    }

    // Iterate over all possible binary strings of length k
    for (int i = 0; i <= s.length() - k; i++) {
        String substring = s.substring(i, i + k);

        // Check if the substring is a valid binary string
        if (!substring.matches("(0|1)+")) {
            return false;
        }

        // Check if the substring is a substring of s
        if (!s.contains(substring)) {
            return false;
        }
    }

    return true;
}

