public static int minOperations(int n) {
    int minOperations = 0;
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }
    while (true) {
        boolean allEqual = true;
        for (int i = 1; i < n; i++) {
            if (arr[i] != arr[0]) {
                allEqual = false;
                break;
            }
        }
        if (allEqual) {
            break;
        }
        minOperations++;
        int smallest = Integer.MAX_VALUE;
        int largest = Integer.MIN_VALUE;
        for (int i = 0; i < n; i++) {
            if (arr[i] < smallest) {
                smallest = arr[i];
            }
            if (arr[i] > largest) {
                largest = arr[i];
            }
        }
        int first = 0;
        while (arr[first] == smallest) {
            first++;
        }
        int second = 0;
        while (arr[second] == largest) {
            second++;
        }
        arr[first] -= 1;
        arr[second] += 1;
    }
    return minOperations;
}

public int minOperations(int n) {
    int operations = 0;
    for (int i = 0; i < n; i++) {
        int diff = arr[i] - (2 * i + 1);
        operations += Math.abs(diff);
        arr[i] -= diff;
    }
    return operations;
}

