    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }
    int result = 0;
    while (true) {
        int min = Integer.MAX_VALUE;
        int max = Integer.MIN_VALUE;
        for (int i = 0; i < n; i++) {
            if (arr[i] < min) {
                min = arr[i];
            }
            if (arr[i] > max) {
                max = arr[i];
            }
        }
        if (min == max) {
            break;
        }
        for (int i = 0; i < n; i++) {
            if (arr[i] == min) {
                arr[i] = max;
                result++;
            }
        }
    }
    return result;
}

public int minOperations(int n) {
    int arr[] = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }
    int min = Integer.MAX_VALUE;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i != j && arr[i] != arr[j]) {
                min = Math.min(min, Math.abs(arr[i] - arr[j]));
            }
        }
    }
    return n - 1 + min;
}

