public int findMinFibonacciNumbers(int k) {
    int fib1 = 1, fib2 = 1;
    int minNumFibonacciNumbers = 0;
    while (fib1 <= k) {
        if (fib1 + fib2 <= k) {
            minNumFibonacciNumbers++;
            fib1 = fib2;
            fib2 = fib1 + fib2;
        } else {
            break;
        }
    }
    return minNumFibonacciNumbers;
}

public int findMinFibonacciNumbers(int k) {
    int[] fibonacciNumbers = new int[k + 1];
    fibonacciNumbers[0] = 0;
    fibonacciNumbers[1] = 1;
    for (int i = 2; i <= k; i++) {
        fibonacciNumbers[i] = fibonacciNumbers[i - 1] + fibonacciNumbers[i - 2];
    }
    int minFibonacciNumbers = 0;
    for (int i = k; i >= 1; i--) {
        if (fibonacciNumbers[i] <= k) {
            minFibonacciNumbers++;
            k -= fibonacciNumbers[i];
        }
    }
    return minFibonacciNumbers;
}

