        return 1;
    }
    int n = s.length();
    boolean[][] dp = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        dp[i][i] = true;
    }
    int max = 1;
    for (int i = 0; i < n - 1; i++) {
        if (s.charAt(i) == s.charAt(i + 1)) {
            dp[i][i + 1] = true;
        }
        max = Math.max(max, dp[i][i + 1] ? 2 : 1);
    }
    for (int i = 2; i < n; i++) {
        for (int j = 0; j < n - i; j++) {
            int k = j + i;
            if (dp[j + 1][k - 1] && s.charAt(j) != s.charAt(k)) {
                dp[j][k] = true;
                max = Math.max(max, 2 + (j > 0 ? dp[0][j - 1] : 0) + (k < n - 1 ? dp[k + 1][n - 1] : 0));
            }
        }
    }
    return max;
}

