public String getSmallestString(int n, int k) {
    String ans = "";
    int alphabetSize = 26;
    while (n > 0) {
        int remaining = k - alphabetSize * (n - 1);
        char c = (char) ('a' + remaining - 1);
        ans = c + ans;
        n--;
        k = remaining - 1;
    }
    return ans;
}

