}

public String getSmallestString(int n, int k) {
    char[] chars = new char[n];
    Arrays.fill(chars, 'a');
    int remaining = k - n;
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        chars[i] = (char) ('a' + remaining % 26);
        remaining /= 26;
    }
    return new String(chars);
}

public String getSmallestString(int n, int k) {
    char[] chars = new char[n];
    Arrays.fill(chars, 'a');
    while (k > 0) {
        int index = k - 1;
        while (index >= 0 && chars[index] == 'z') {
            index--;
        }
        chars[index]++;
        k -= index + 1;
    }
    return String.valueOf(chars);
}

