public static int longestLine(int[][] mat) {
    // Initialize the maximum length of the line to 0
    int maxLen = 0;

    // Loop through each row in the matrix
    for (int i = 0; i < mat.length; i++) {
        // Loop through each column in the row
        for (int j = 0; j < mat[i].length; j++) {
            // If the current element is 1, check if it is part of a line
            if (mat[i][j] == 1) {
                // Check the current element and the ones above, below, left, and right of it
                maxLen = Math.max(maxLen, countLine(mat, i, j));
            }
        }
    }

    return maxLen;
}

private static int countLine(int[][] mat, int i, int j) {
    // Initialize the length of the line to 1
    int len = 1;

    // Check if the current element is part of a horizontal line
    if (mat[i][j] == 1 && mat[i][j + 1] == 1) {
        // Count the length of the horizontal line
        len += countLine(mat, i, j + 1);
    }

    // Check if the current element is part of a vertical line
    if (mat[i][j] == 1 && mat[i + 1][j] == 1) {
        // Count the length of the vertical line
        len += countLine(mat, i + 1, j);
    }

    // Check if the current element is part of a diagonal line
    if (mat[i][j] == 1 && mat[i + 1][j + 1] == 1) {
        // Count the length of the diagonal line
        len += countLine(mat, i + 1, j + 1);
    }

    // Check if the current element is part of an anti-diagonal line
    if (mat[i][j] == 1 && mat[i - 1][j + 1] == 1) {
        // Count the length of the anti-diagonal line
        len += countLine(mat, i - 1, j + 1);
    }

    return len;
}

public static int longestLine(int[][] mat) {
    int m = mat.length;
