    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                int currentLength = 1;
                while (i + currentLength < m && j + currentLength < n && mat[i + currentLength][j + currentLength] == 1) {
                    currentLength++;
                }
                if (currentLength > maxLength) {
                    maxLength = currentLength;
                }
            }
        }
    }

    // Anti-diagonal line
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                int currentLength = 1;
                while (i + currentLength < m && j - currentLength >= 0 && mat[i + currentLength][j - currentLength] == 1) {
                    currentLength++;
                }
                if (currentLength > maxLength) {
                    maxLength = currentLength;
                }
            }
        }
    }

