    int maxLen = 0;

    // Loop through each cell in the matrix
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            // Check if the current cell is 1
            if (mat[i][j] == 1) {
                // If so, recursively find the longest line starting from this cell
                int currLen = findLongestLine(mat, i, j, m, n);

                // Update the maximum length if necessary
                maxLen = Math.max(maxLen, currLen);
            }
        }
    }

    return maxLen;
}

private static int findLongestLine(int[][] mat, int i, int j, int m, int n) {
    // If the current cell is not 1 or if we are outside the matrix, return 0
    if (mat[i][j] != 1 || i < 0 || i >= m || j < 0 || j >= n) {
        return 0;
    }

    // Recursively find the lengths of the lines starting from the adjacent cells
    int adjCell1 = findLongestLine(mat, i - 1, j, m, n);
    int adjCell2 = findLongestLine(mat, i, j - 1, m, n);
    int adjCell3 = findLongestLine(mat, i - 1, j - 1, m, n);
    int adjCell4 = findLongestLine(mat, i + 1, j - 1, m, n);

    // Return the maximum of the lengths of all the adjacent cells
    return Math.max(adjCell1, adjCell2, adjCell3, adjCell4) + 1;
}

