            maxConsecutive = Math.max(maxConsecutive, consecutive);

            // vertical
            consecutive = 1;
            for (int k = i + 1; k < mat.length; k++) {
                if (mat[i][j] == 1 && mat[k][j] == 1) {
                    consecutive++;
                } else {
                    break;
                }
            }
            maxConsecutive = Math.max(maxConsecutive, consecutive);

            // diagonal
            consecutive = 1;
            for (int k = 1; k < Math.min(mat.length, mat[0].length) - j; k++) {
                if (mat[i][j] == 1 && mat[i + k][j + k] == 1) {
                    consecutive++;
                } else {
                    break;
                }
            }
            maxConsecutive = Math.max(maxConsecutive, consecutive);

            // anti-diagonal
            consecutive = 1;
            for (int k = 1; k < Math.min(mat.length, mat[0].length) - j; k++) {
                if (mat[i][j] == 1 && mat[i + k][j - k] == 1) {
                    consecutive++;
                } else {
                    break;
                }
            }
            maxConsecutive = Math.max(maxConsecutive, consecutive);
        }
    }
    return maxConsecutive;
}

