public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];
    int[] maxArea = new int[n];

    left[0] = -1;
    right[n-1] = n;
    for (int i = 1; i < n; i++) {
        int idx = i - 1;
        while (idx >= 0 && heights[idx] >= heights[i]) {
            idx = left[idx];
        }
        left[i] = idx;
    }

    for (int i = n - 2; i >= 0; i--) {
        int idx = i + 1;
        while (idx < n && heights[idx] >= heights[i]) {
            idx = right[idx];
        }
        right[i] = idx;
    }

    for (int i = 0; i < n; i++) {
        maxArea[i] = Math.min(heights[i], heights[left[i]] * (i - left[i]));
        maxArea[i] = Math.min(maxArea[i], heights[right[i]] * (right[i] - i));
    }

    int maxAreaIdx = 0;
    for (int i = 1; i < n; i++) {
        if (maxArea[i] > maxArea[maxAreaIdx]) {
            maxAreaIdx = i;
        }
    }

    return maxArea[maxAreaIdx];
}

public static int largestRectangleArea(int[] heights) {
