    Stack<Integer> stack = new Stack<>();

    for (int i = 0; i <= n; i++) {
        int h = i == n ? 0 : heights[i];
        if (stack.isEmpty() || h >= heights[stack.peek()]) {
            stack.push(i);
        } else {
            int top = stack.pop();
            int area = heights[top] * (stack.isEmpty() ? i : i - stack.peek() - 1);
