private static boolean next_permutation(int[] numDigits) {
    int i = numDigits.length - 2;
    while (i >= 0 && numDigits[i] >= numDigits[i + 1]) {
        i--;
    }
    if (i == -1) {
        return false;
    }
    int j = numDigits.length - 1;
    while (numDigits[j] <= numDigits[i]) {
        j--;
    }
    swap(numDigits, i, j);
    reverse(numDigits, i + 1);
    return true;
}

private static void swap(int[] numDigits, int i, int j) {
    int temp = numDigits[i];
    numDigits[i] = numDigits[j];
    numDigits[j] = temp;
}

private static void reverse(int[] numDigits, int start) {
    int i = start, j = numDigits.length - 1;
    while (i < j) {
        swap(numDigits, i, j);
        i++;
        j--;
    }
}

