public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) return false;
    int[][] copy = copyArray(points);
    Arrays.sort(copy, Comparator.comparingInt(a -> a[0]));
    for (int i = 0; i < 3; i++) {
        int x = copy[i][0];
        int y = copy[i][1];
        int nextX = copy[(i + 1) % 3][0];
        int nextY = copy[(i + 1) % 3][1];
        int nextNextX = copy[(i + 2) % 3][0];
        int nextNextY = copy[(i + 2) % 3][1];
        double distance1 = Math.sqrt(Math.pow(x - nextX, 2) + Math.pow(y - nextY, 2));
        double distance2 = Math.sqrt(Math.pow(nextX - nextNextX, 2) + Math.pow(nextY - nextNextY, 2));
        double distance3 = Math.sqrt(Math.pow(x - nextNextX, 2) + Math.pow(y - nextNextY, 2));
        double maxDistance = Math.max(distance1, Math.max(distance2, distance3));
        double minDistance = Math.min(distance1, Math.min(distance2, distance3));
        if (minDistance / maxDistance < 0.5) return false;
    }
    return true;
}

