public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();

    for (int i = 1; i <= n; i++) {
        result.add(i);
    }

    Collections.sort(result);

    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        result.add(i);
    }
    for (int i = 10; i <= n; i++) {
        if (i % 10 == 0) {
            result.add(i);
            continue;
        }
        int digit = i % 10;
        int j = i - digit;
        if (j >= result.size()) {
            result.add(i);
        } else {
            result.add(j, i);
        }
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        result.add(i);
    }
    for (int i = 10; i <= n; i++) {
        String s = String.valueOf(i);
        int idx = result.size();
        while (idx > 0 && String.valueOf(result.get(idx - 1)).compareTo(s) > 0) {
            idx--;
        }
        result.add(idx, i);
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        result.add(i);
    }
    result.sort(Comparator.naturalOrder());
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        result.add(i);
    }
    int curr = 10, j = 1;
    while (curr <= n) {
        result.add(curr);
        curr = (int) Math.pow(10, j);
        j++;
    }
    return result;
}

