public static int minPerfectSquareSum(int n) {
    int minSquares = 0;
    int currentSquare = 1;
    while (currentSquare <= n) {
        if (currentSquare == n) {
            minSquares++;
            break;
        } else if (currentSquare < n) {
            minSquares++;
            currentSquare += 4 * currentSquare + 1;
        }
    }
    return minSquares;
}

public static int minPerfectSquareSum(int n) {
    int minSquares = 0;
    for (int i = 1; i * i <= n; i++) {
        minSquares++;
        n -= i * i;
        if (n == 0) {
            break;
        }
    }
    return minSquares;
}

public static int minPerfectSquareSum(int n) {
    int count = 0, sum = 0;
    for (int i = 1; sum < n; i++) {
        sum += i * i;
        count++;
    }
    return count;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    int sum = 0;
    while (sum < n) {
        int perfectSquare = (int) Math.pow(count, 2);
        sum += perfectSquare;
        count++;
    }
    return count - 1;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int minSquares = 1;
    int currentSquare = 1;
    while (currentSquare <= n / 2) {
        if (n - currentSquare >= 0) {
            minSquares++;
            n -= currentSquare;
        }
        currentSquare += 2;
    }
    return minSquares;
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    String reversedWords = "";
    for (String word : words) {
        char[] wordChars = word.toCharArray();
        String reversedWord = "";
        for (int i = wordChars.length - 1; i >= 0; i--) {
            reversedWord += wordChars[i];
        }
        reversedWords += reversedWord + " ";
    }
    return reversedWords;
}

public static String reverseWords(String s) {
    StringBuilder sb = new StringBuilder();
    String[] words = s.split(" ");
    for (int i = 0; i < words.length; i++) {
        sb.append(new StringBuilder(words[i]).reverse());
        if (i < words.length - 1) {
            sb.append(" ");
        }
    }
    return sb.toString();
}

